import os
import sys

import Pyro4
from hran_elementmanager2g.utils.constants import (DEFAULT_BTS_IP, DEFAULT_BTS_PORT, DEFAULT_PASSWORD, DEFAULT_BTS_BCF,
    DAEMON_HOST, DAEMON_PORT, PYRO_SERVER_NAME, SERVER_VERSION, SERIALIZERS_ACCEPTED, return_ironpython_path)
from hran_elementmanager2g.wrapper import ElementManager2G, OutputHandler

Pyro4.config.SERIALIZERS_ACCEPTED = SERIALIZERS_ACCEPTED
Pyro4.config.REQUIRE_EXPOSE = False


class PyroServer(ElementManager2G, OutputHandler):

    def __init__(self, bts_ip=DEFAULT_BTS_IP, bts_port=DEFAULT_BTS_PORT, bts_password=DEFAULT_PASSWORD,
                 bts_bcf=DEFAULT_BTS_BCF, pyro_port=DAEMON_PORT):
        super(PyroServer, self).__init__(host=bts_ip, port=bts_port, password=bts_password, bcfnumber=bts_bcf)
        sys.stdout = OutputHandler()
        self.uri = None
        self.server_version = SERVER_VERSION
        self.running = True
        self.pyro_port = pyro_port
        self.tc = None
        self.daemon = None

    def start_server(self, host_ip=DAEMON_HOST):
        with Pyro4.Daemon(host=host_ip, port=self.pyro_port) as daemon:
            self.uri = daemon.register(self, objectId=PYRO_SERVER_NAME)
            self.running = True
            self.daemon = daemon
            print("element_manager_pyro_server_running")
            daemon.requestLoop()

    def get_server_version(self):
        return self.server_version

    def stop_server(self):
        self.running = False
        self.daemon.shutdown()
        return True

    def logfile_path(self):
        logile = sys.stdout.return_logfile()
        return logile

    def get_server_status(self):
        return self.running

    def get_message_list(self):
        temporary = [x for message in self.message_list for x in message.split()]  # remove newline ('\n') list elements
        self.message_list[:] = []  # clear list content so as to get only prints from a single function
        loglist = []
        for str in temporary:
            loglist.append(''.join(i for i in str if ord(i) < 128))
        return loglist

    def get_current_user_homepath(self):
        return os.path.expanduser('~')

    def check_server_pyro_version(self):
        cmd = r'"'"{path}"'" -c "import Pyro4.constants as c; print(c.PROTOCOL_VERSION)"'.format(
            path=return_ironpython_path().replace("\\", "/"))
        return os.popen(cmd).read().rstrip()

    def convert_windows_to_cygwin_path(self, path):
        try:
            return os.popen('cygpath "{}"'.format(path)).read().rstrip()
        except:
            return 'Bad path given or cannot run cygpath command!'


if __name__ == '__main__':
    if len(sys.argv) == 6:
        server = PyroServer(bts_ip=sys.argv[1], bts_port=int(sys.argv[2]), bts_password=sys.argv[3],
                            bts_bcf=int(sys.argv[4]), pyro_port=int(sys.argv[5]))
        server.start_server()
        print('server daemon closed')
    else:
        print('wrong on incomplete parameters')
        print('command line interface syntax:')
        print('server_runner.py <bts_ip> <bts_port> <bts_password> <bts_bcf> <bts_debug>')
